import { CourseChapter } from "./courseContent";

export function getMassagePostpartumChapters(): CourseChapter[] {
  return [
    {
      title: "Jour 1 – Fondamentaux et cadre du massage prénatal",
      description: "Comprendre les bases du massage prénatal, le cadre professionnel, l'hygiène, la sécurité et la posture du praticien.",
      sections: [
        { title: "Présentation de la formation et objectifs", content: `<p>La formation <strong>Massage Postpartum</strong> (38 heures – 6 jours) vise à former des praticiens capables de réaliser des séances de massage adaptées à la femme enceinte et en post-partum. Cette formation s'inscrit dans une approche holistique du bien-être maternel.</p><p><strong>Objectifs généraux :</strong></p><ul><li>Savoir mettre en place et appliquer des séances de relaxation pendant la grossesse grâce à différentes pratiques</li><li>Permettre à la femme enceinte de visualiser son schéma corporel en toute douceur à travers des techniques de respiration et palpation</li><li>Accompagner la future maman afin de vivre la naissance en toute conscience</li><li>Maîtriser un protocole complet de massage prénatal et postpartum</li></ul><p><strong>Public visé :</strong> Toute personne souhaitant acquérir les compétences de massage prénatal et postpartum, professionnels du bien-être, sage-femmes, kinésithérapeutes, esthéticiennes.</p><p><strong>Prérequis :</strong> Aucun prérequis nécessaire à la formation.</p><p><strong>Organisation :</strong> 6 jours de formation en présentiel, alternant théorie et pratique intensive. Chaque journée comprend environ 6h30 de formation (5h30 le dernier jour).</p>` },
        { title: "Historique du massage : approche africaine et bien-être", content: `<p>Le massage prénatal trouve ses racines dans des traditions ancestrales, notamment en Afrique où le toucher fait partie intégrante de l'accompagnement de la femme enceinte :</p><ul><li><strong>Traditions africaines :</strong> Dans de nombreuses cultures africaines, le massage de la femme enceinte est un rituel sacré transmis de mère en fille. Les matrones pratiquent des manœuvres spécifiques pour préparer le corps à l'accouchement et soulager les douleurs liées à la grossesse.</li><li><strong>Le massage comme lien social :</strong> En Afrique de l'Ouest, le massage postpartum fait partie d'un rituel de 40 jours après l'accouchement. La jeune maman est massée quotidiennement par les femmes de la communauté pour favoriser la récupération physique et le lien avec le nouveau-né.</li><li><strong>Approche holistique :</strong> Le massage africain ne dissocie pas le corps de l'esprit. Il intègre des chants, des prières et des huiles végétales locales (karité, baobab, coco) pour envelopper la femme dans un cocon de bienveillance.</li></ul><p><strong>Évolution contemporaine :</strong> Ces pratiques ancestrales ont été intégrées dans les protocoles modernes de massage prénatal, enrichies par les connaissances en anatomie, physiologie et sécurité. Le massage bien-être s'est professionnalisé tout en conservant cette dimension humaine et empathique.</p><table border="1" cellpadding="8" style="width:100%;border-collapse:collapse"><tr style="background:#f0f0f0"><th>Tradition</th><th>Spécificité</th><th>Produit utilisé</th></tr><tr><td>Afrique de l'Ouest</td><td>Massage postpartum sur 40 jours</td><td>Beurre de karité</td></tr><tr><td>Inde (Ayurveda)</td><td>Abhyanga – massage à l'huile chaude</td><td>Huile de sésame</td></tr><tr><td>Thaïlande</td><td>Massage thaï adapté (pas d'étirements profonds)</td><td>Baumes aux herbes</td></tr><tr><td>Hawaï</td><td>Lomi-Lomi prénatal</td><td>Huile de noix de kukui</td></tr></table>` },
        { title: "Définition et bienfaits du massage prénatal", content: `<p><strong>Définition :</strong> Le massage prénatal est un ensemble de techniques manuelles douces, adaptées aux spécificités physiologiques de la femme enceinte, visant à soulager les tensions musculaires, améliorer la circulation sanguine et lymphatique, et favoriser la détente psycho-émotionnelle.</p><p><strong>Bienfaits physiques :</strong></p><ul><li>Soulagement des douleurs lombaires et dorsales (lordose de grossesse)</li><li>Réduction des œdèmes des membres inférieurs par drainage lymphatique doux</li><li>Diminution des crampes musculaires (mollets, pieds)</li><li>Amélioration de la qualité du sommeil</li><li>Soulagement des céphalées de tension</li><li>Prévention des vergetures par hydratation et stimulation cutanée</li></ul><p><strong>Bienfaits psychologiques :</strong></p><ul><li>Réduction significative du cortisol (hormone du stress) – études montrant une baisse de 25% après une séance</li><li>Augmentation de la sérotonine et de la dopamine (hormones du bien-être)</li><li>Sécrétion d'ocytocine favorisant le lien mère-bébé</li><li>Diminution de l'anxiété liée à l'accouchement</li><li>Amélioration de l'image corporelle positive</li><li>Sentiment de sécurité et de soutien</li></ul><p><strong>Étude de référence :</strong> Field et al. (2004) ont démontré que les femmes enceintes recevant un massage bihebdomadaire présentaient moins de dépression prénatale, moins de douleurs dorsales et des bébés de poids de naissance plus élevé.</p>` },
        { title: "Cadre légal : massage bien-être vs thérapeutique", content: `<p>Il est essentiel de distinguer le massage bien-être du massage thérapeutique pour exercer en toute légalité :</p><table border="1" cellpadding="8" style="width:100%;border-collapse:collapse"><tr style="background:#f0f0f0"><th>Critère</th><th>Massage bien-être</th><th>Massage thérapeutique</th></tr><tr><td>Objectif</td><td>Détente, relaxation, confort</td><td>Traitement d'une pathologie</td></tr><tr><td>Praticien</td><td>Praticien en massage bien-être</td><td>Kinésithérapeute, médecin</td></tr><tr><td>Prescription</td><td>Non prescrit</td><td>Sur ordonnance médicale</td></tr><tr><td>Remboursement</td><td>Non remboursé par la Sécurité Sociale</td><td>Remboursé (avec ordonnance)</td></tr><tr><td>Formation</td><td>Certification professionnelle</td><td>Diplôme d'État (MKDE)</td></tr><tr><td>Terminologie</td><td>« Massage de relaxation », « modelage »</td><td>« Masso-kinésithérapie »</td></tr></table><p><strong>Points clés juridiques :</strong></p><ul><li>L'article L.4321-1 du Code de la santé publique réserve le terme « massage » aux kinésithérapeutes dans un contexte thérapeutique</li><li>En tant que praticien bien-être, utiliser les termes « modelage », « techniques manuelles de relaxation » ou « soins corporels de bien-être »</li><li>Ne jamais établir de diagnostic médical</li><li>Ne jamais promettre de résultat thérapeutique</li><li>Toujours orienter vers un professionnel de santé en cas de symptômes préoccupants</li></ul>` },
        { title: "Hygiène et sécurité du praticien et de l'environnement", content: `<p><strong>Hygiène du praticien :</strong></p><ul><li>Lavage des mains avant et après chaque séance (eau + savon 30 secondes minimum, ou SHA)</li><li>Ongles courts et sans vernis</li><li>Cheveux attachés</li><li>Tenue professionnelle propre et confortable</li><li>Pas de bijoux (bagues, bracelets) pouvant blesser la cliente</li></ul><p><strong>Environnement de travail :</strong></p><ul><li><strong>Température :</strong> 22-24°C (la femme enceinte est plus sensible au froid)</li><li><strong>Éclairage :</strong> Lumière tamisée, bougies LED (pas de vraies bougies pour la sécurité)</li><li><strong>Son :</strong> Musique douce et relaxante, volume bas</li><li><strong>Odeurs :</strong> Éviter les parfums forts, pas de diffusion d'huiles essentielles sans avis médical</li><li><strong>Matériel :</strong> Table de massage confortable (hauteur réglable), coussins de positionnement, draps et serviettes propres à chaque cliente</li></ul><p><strong>Checklist sécurité :</strong></p><ol><li>Vérifier que l'espace est dégagé (aucun obstacle au sol)</li><li>S'assurer que la table supporte le poids de la cliente</li><li>Avoir de l'eau à disposition</li><li>Connaître les numéros d'urgence</li><li>Disposer d'une trousse de premiers secours</li></ol>` },
        { title: "Posture du praticien", content: `<p>La posture du praticien est fondamentale pour prévenir les troubles musculo-squelettiques et garantir l'efficacité des manœuvres :</p><p><strong>Principes de base :</strong></p><ul><li><strong>Position des pieds :</strong> Écartés à la largeur du bassin, un pied légèrement en avant (position de fente) pour la stabilité</li><li><strong>Genoux :</strong> Légèrement fléchis, jamais verrouillés</li><li><strong>Bassin :</strong> Basculé en antéversion légère, centre de gravité bas</li><li><strong>Dos :</strong> Droit, allongé, sans cambrure excessive ni arrondissement</li><li><strong>Épaules :</strong> Basses et détendues, loin des oreilles</li><li><strong>Bras :</strong> Coudes légèrement fléchis, poignets dans l'alignement de l'avant-bras</li></ul><p><strong>Ergonomie de travail :</strong></p><table border="1" cellpadding="8" style="width:100%;border-collapse:collapse"><tr style="background:#f0f0f0"><th>Zone massée</th><th>Position du praticien</th><th>Hauteur de table recommandée</th></tr><tr><td>Dos</td><td>Côté de la table, fente avant</td><td>À hauteur de la cuisse du praticien</td></tr><tr><td>Jambes</td><td>En bout de table ou sur le côté</td><td>Même hauteur</td></tr><tr><td>Pieds</td><td>Assis en bout de table</td><td>Sur un tabouret à roulettes</td></tr><tr><td>Visage/crâne</td><td>Assis en tête de table</td><td>Sur un tabouret réglable</td></tr></table><p><strong>Exercice pratique :</strong> Travail en binôme sur la posture – le formateur corrige individuellement chaque participant pendant 15 minutes de pratique sur table.</p>` },
        { title: "Exercices de recentrage et respiration", content: `<p>La mise en condition du praticien est aussi importante que celle de la cliente. Avant chaque séance, le praticien doit se recentrer :</p><p><strong>Exercice 1 : Ancrage au sol (2 minutes)</strong></p><ol><li>Debout, pieds nus si possible, écartés à la largeur du bassin</li><li>Fermer les yeux, sentir le contact des pieds avec le sol</li><li>Visualiser des racines qui partent de la plante des pieds et s'enfoncent dans le sol</li><li>Respirer lentement en sentant cette connexion à la terre</li></ol><p><strong>Exercice 2 : Respiration carrée (3 minutes)</strong></p><ol><li>Inspirer sur 4 temps par le nez</li><li>Retenir le souffle sur 4 temps</li><li>Expirer sur 4 temps par la bouche</li><li>Retenir poumons vides sur 4 temps</li><li>Répéter 6 à 8 cycles</li></ol><p><strong>Exercice 3 : Activation des mains (2 minutes)</strong></p><ol><li>Frotter vigoureusement les paumes l'une contre l'autre pendant 30 secondes</li><li>Écarter les mains de 5 cm et sentir la chaleur entre les paumes</li><li>Ouvrir et fermer les doigts lentement, 10 fois</li><li>Masser chaque doigt de la base à l'extrémité</li><li>Secouer les mains vigoureusement</li></ol><p><strong>Objectif :</strong> Arriver devant la cliente en étant pleinement présent, centré et détendu. Le toucher transmet l'état émotionnel du praticien – il doit être serein.</p>` },
      ]
    },
    {
      title: "Jour 2 – Anatomie et grossesse",
      description: "Comprendre les transformations du corps pendant la grossesse, les 3 trimestres, les contre-indications et les produits adaptés.",
      sections: [
        { title: "Les transformations du corps pendant la grossesse", content: `<p>La grossesse entraîne des modifications profondes de l'organisme maternel. Le praticien doit les connaître pour adapter ses techniques :</p><p><strong>Système musculo-squelettique :</strong></p><ul><li><strong>Lordose lombaire :</strong> Accentuation de la courbure lombaire due au poids du ventre, entraînant des douleurs dorsales</li><li><strong>Hyperlaxité ligamentaire :</strong> La relaxine (hormone produite dès le 1er trimestre) assouplit les ligaments, rendant les articulations plus mobiles mais plus fragiles</li><li><strong>Diastasis des grands droits :</strong> Écartement des muscles abdominaux pour accommoder la croissance utérine</li><li><strong>Modification du centre de gravité :</strong> Déplacement vers l'avant, augmentant le risque de chute</li></ul><p><strong>Système circulatoire :</strong></p><ul><li>Augmentation du volume sanguin de 40-50% (de 5L à environ 7L)</li><li>Fréquence cardiaque augmentée de 10-20 bpm</li><li>Compression de la veine cave inférieure par l'utérus en position dorsale (syndrome de la veine cave)</li><li>Risque accru de varices, hémorroïdes et œdèmes des membres inférieurs</li><li>Hypotension orthostatique fréquente</li></ul><p><strong>Système hormonal :</strong></p><table border="1" cellpadding="8" style="width:100%;border-collapse:collapse"><tr style="background:#f0f0f0"><th>Hormone</th><th>Rôle</th><th>Impact sur le massage</th></tr><tr><td>Relaxine</td><td>Assouplit les ligaments</td><td>Éviter les étirements excessifs</td></tr><tr><td>Progestérone</td><td>Maintien de la grossesse, relaxation musculaire</td><td>Somnolence fréquente, muscles plus détendus</td></tr><tr><td>Œstrogènes</td><td>Développement utérin, préparation lactation</td><td>Sensibilité cutanée accrue</td></tr><tr><td>Ocytocine</td><td>Hormone de l'attachement</td><td>Libérée par le toucher bienveillant</td></tr><tr><td>Cortisol</td><td>Hormone du stress</td><td>Réduit significativement par le massage</td></tr></table>` },
        { title: "Les 3 trimestres et leurs spécificités", content: `<p>Chaque trimestre présente des caractéristiques spécifiques qui influencent directement la pratique du massage :</p><p><strong>1er Trimestre (SA 1 à 14) :</strong></p><ul><li><strong>État de la cliente :</strong> Nausées, fatigue intense, sensibilité émotionnelle accrue, seins douloureux</li><li><strong>Précautions massage :</strong> De nombreux praticiens évitent de masser au 1er trimestre par principe de précaution (risque de fausse couche spontanée). Si massage autorisé par le médecin, uniquement des effleurages très légers.</li><li><strong>Zones à privilégier :</strong> Pieds (hors points d'acupression), mains, cuir chevelu</li><li><strong>À éviter :</strong> Abdomen, zone lombaire profonde, huiles essentielles</li></ul><p><strong>2ème Trimestre (SA 15 à 28) :</strong></p><ul><li><strong>État :</strong> « Lune de miel » de la grossesse – énergie retrouvée, ventre visible mais pas trop volumineux</li><li><strong>Période idéale :</strong> C'est le trimestre le plus favorable au massage prénatal</li><li><strong>Positions possibles :</strong> Décubitus latéral, semi-assise</li><li><strong>Techniques :</strong> Effleurage, pétrissage doux, drainage léger des jambes</li></ul><p><strong>3ème Trimestre (SA 29 à 40) :</strong></p><ul><li><strong>État :</strong> Ventre volumineux, essoufflement, douleurs lombaires et pelviennes, insomnie, œdèmes</li><li><strong>Adaptation :</strong> Séances plus courtes (45 min max), pression très douce, positionnement latéral exclusif</li><li><strong>Focus :</strong> Soulagement du dos, drainage des jambes, préparation du périnée, relaxation</li><li><strong>Attention :</strong> Surveiller les signes de contractions, vertiges ou malaise</li></ul>` },
        { title: "Les contre-indications", content: `<p>La connaissance des contre-indications est <strong>impérative</strong> pour la sécurité de la mère et du bébé :</p><p><strong>Contre-indications absolues (massage interdit) :</strong></p><ul><li>Grossesse à risque avec menace d'accouchement prématuré (MAP)</li><li>Pré-éclampsie (hypertension artérielle + protéinurie + œdèmes)</li><li>Placenta praevia (insertion basse du placenta)</li><li>Saignements vaginaux inexpliqués</li><li>Fièvre supérieure à 38°C ou infection active</li><li>Contractions régulières avant 37 SA</li><li>Béance cervicale (cerclage du col)</li><li>Retard de croissance intra-utérin (RCIU) sévère</li><li>Phlébite ou thrombose veineuse profonde</li></ul><p><strong>Contre-indications relatives (adapter ou reporter) :</strong></p><ul><li>Hypertension artérielle modérée (adapter la position)</li><li>Diabète gestationnel (surveiller les signes d'hypoglycémie)</li><li>Douleurs abdominales inhabituelles (reporter et consulter)</li><li>Nausées sévères (adapter la durée)</li><li>Maux de tête intenses et persistants (exclure pré-éclampsie)</li></ul><p><strong>Protocole en cas de doute :</strong></p><ol><li>Demander un certificat médical de non-contre-indication</li><li>En cas de symptôme pendant la séance : arrêter immédiatement</li><li>Installer la cliente en décubitus latéral gauche</li><li>Appeler les secours si nécessaire</li></ol>` },
        { title: "Les produits adaptés : huiles et soins", content: `<p>Le choix des produits est crucial pendant la grossesse. De nombreuses substances couramment utilisées en massage sont potentiellement dangereuses :</p><p><strong>Huiles végétales recommandées :</strong></p><table border="1" cellpadding="8" style="width:100%;border-collapse:collapse"><tr style="background:#f0f0f0"><th>Huile</th><th>Propriétés</th><th>Utilisation</th><th>Prix indicatif</th></tr><tr><td>Amande douce</td><td>Adoucissante, hypoallergénique, pénétration lente</td><td>Base universelle, tous les trimestres</td><td>8-12€/250ml</td></tr><tr><td>Jojoba</td><td>Régulatrice, non comédogène, glisse longue</td><td>Peaux mixtes, excellente pour le visage</td><td>12-18€/100ml</td></tr><tr><td>Argan</td><td>Nourrissante, régénérante, anti-vergetures</td><td>Ventre, cuisses, poitrine (prévention vergetures)</td><td>15-25€/100ml</td></tr><tr><td>Coco (fractionnée)</td><td>Hydratante, antibactérienne, absorption rapide</td><td>Massage léger, climats chauds</td><td>8-15€/250ml</td></tr><tr><td>Calendula (macérât)</td><td>Apaisante, anti-inflammatoire</td><td>Peaux sensibles, irritations</td><td>10-15€/100ml</td></tr></table><p><strong>Huiles essentielles – ATTENTION :</strong></p><ul><li><strong>INTERDIT au 1er trimestre :</strong> Toutes les huiles essentielles</li><li><strong>INTERDIT toute la grossesse :</strong> Sauge, romarin, menthe poivrée, cannelle, clou de girofle, thym, origan, eucalyptus, camphre</li><li><strong>Utilisables après avis médical (2ème/3ème trimestre, très diluées) :</strong> Lavande vraie, ylang-ylang, petit grain bigarade</li><li><strong>Règle d'or :</strong> En cas de doute, ne pas utiliser d'huile essentielle</li></ul>` },
        { title: "Les zones sensibles et points à éviter", content: `<p>Certaines zones du corps nécessitent une attention particulière pendant la grossesse :</p><p><strong>Points d'acupression à ÉVITER absolument :</strong></p><table border="1" cellpadding="8" style="width:100%;border-collapse:collapse"><tr style="background:#f0f0f0"><th>Point</th><th>Localisation</th><th>Risque</th></tr><tr><td>Hegu (GI4)</td><td>Entre le pouce et l'index</td><td>Stimule les contractions utérines</td></tr><tr><td>Sanyinjiao (Rt6)</td><td>4 travers de doigt au-dessus de la malléole interne</td><td>Déclenche le travail</td></tr><tr><td>Jianjing (VB21)</td><td>Sommet de l'épaule (trapèze)</td><td>Stimule la descente du bébé</td></tr><tr><td>Kunlun (V60)</td><td>Derrière la malléole externe</td><td>Favorise la dilatation du col</td></tr></table><p><strong>Zones nécessitant des précautions :</strong></p><ul><li><strong>Abdomen :</strong> Uniquement des effleurages très légers et circulaires (sens horaire) au 2ème trimestre. Aucune pression au 3ème trimestre.</li><li><strong>Poitrine :</strong> Zone très sensible, ne masser que si la cliente le souhaite. Effleurage uniquement.</li><li><strong>Sacrum :</strong> Pas de pression profonde au 3ème trimestre (risque de stimuler le travail)</li><li><strong>Veines variqueuses :</strong> Ne jamais masser directement dessus – contourner la zone</li><li><strong>Zone inguinale :</strong> Zone ganglionnaire à traiter avec délicatesse</li></ul>` },
        { title: "Positionnement de la cliente – Mise en situation", content: `<p>L'installation de la femme enceinte est <strong>l'étape la plus importante</strong> de la séance. Un mauvais positionnement peut provoquer un malaise ou comprimer la veine cave :</p><p><strong>Position 1 : Décubitus latéral gauche (PRIVILÉGIÉE)</strong></p><ul><li>Allongée sur le côté gauche (le côté gauche décomprime la veine cave)</li><li>Coussin sous la tête (hauteur = largeur de l'épaule)</li><li>Coussin entre les genoux (maintien de l'axe du bassin)</li><li>Coussin sous le ventre (support de l'utérus)</li><li>Bras supérieur posé sur un coussin devant elle</li></ul><p><strong>Position 2 : Semi-assise (alternative)</strong></p><ul><li>Dos incliné à 45° sur des coussins ou un plan incliné</li><li>Coussin sous les genoux pour relâcher le bas du dos</li><li>Idéale pour le massage du visage, du cuir chevelu, des mains</li></ul><p><strong>Position 3 : Assise sur chaise ou ballon</strong></p><ul><li>Assise à califourchon sur une chaise avec un coussin sur le dossier</li><li>Ou assise sur un Swiss ball</li><li>Idéale pour le massage du dos, des épaules</li></ul><p><strong>⚠ POSITION INTERDITE à partir du 2ème trimestre :</strong></p><ul><li>Décubitus ventral (sur le ventre) → compression du bébé</li><li>Décubitus dorsal prolongé (sur le dos) → syndrome de la veine cave</li></ul><p><strong>Exercice pratique :</strong> Chaque participant s'exerce à installer une « cliente » (binôme) dans les 3 positions avec chronomètre. Objectif : installation complète en moins de 2 minutes.</p>` },
      ]
    },
    {
      title: "Jour 3 – Techniques de base du massage",
      description: "Apprentissage des gestes fondamentaux : manœuvres de base, techniques de toucher et pression, ergonomie du praticien et fluidité des gestes.",
      sections: [
        { title: "Les manœuvres fondamentales du massage", content: `<p>Le massage prénatal repose sur cinq manœuvres de base, chacune avec un objectif spécifique :</p><table border="1" cellpadding="8" style="width:100%;border-collapse:collapse"><tr style="background:#f0f0f0"><th>Manœuvre</th><th>Description</th><th>Pression</th><th>Objectif</th></tr><tr><td><strong>Effleurage</strong></td><td>Glissement des mains à plat sur la peau, dans le sens du retour veineux</td><td>Légère à modérée</td><td>Réchauffer les tissus, détendre, prendre contact</td></tr><tr><td><strong>Pétrissage</strong></td><td>Saisir, presser et relâcher les tissus en alternance</td><td>Modérée</td><td>Décontracter les muscles tendus</td></tr><tr><td><strong>Pressions glissées</strong></td><td>Pression continue avec la paume ou les pouces le long d'un trajet</td><td>Modérée</td><td>Libérer les tensions profondes</td></tr><tr><td><strong>Friction</strong></td><td>Mouvement circulaire avec le bout des doigts</td><td>Légère</td><td>Détendre les points de tension spécifiques</td></tr><tr><td><strong>Vibrations</strong></td><td>Tremblements fins transmis par les mains</td><td>Très légère</td><td>Relaxation profonde, apaisement</td></tr></table><p><strong>Règle d'or :</strong> En massage prénatal, on travaille toujours en <strong>douceur</strong>. La pression ne doit jamais dépasser le seuil de confort de la cliente. Le praticien demande régulièrement un retour : « Est-ce que la pression vous convient ? »</p>` },
        { title: "Techniques de toucher et qualité de la pression", content: `<p>Le toucher est l'outil principal du praticien. Sa qualité détermine l'efficacité de la séance :</p><p><strong>Les différents types de toucher :</strong></p><ul><li><strong>Toucher d'accueil :</strong> Main posée immobile sur le dos ou l'épaule de la cliente pendant quelques secondes. Premier contact qui instaure la confiance.</li><li><strong>Toucher enveloppant :</strong> Mains ouvertes qui épousent les formes du corps. Sensation de chaleur et de sécurité.</li><li><strong>Toucher précis :</strong> Pouces ou doigts travaillant un point de tension spécifique. Utilisé avec parcimonie chez la femme enceinte.</li><li><strong>Toucher de clôture :</strong> Main qui se retire lentement, avec une légère pression décroissante. Signal que la séance touche à sa fin.</li></ul><p><strong>Échelle de pression (1 à 10) :</strong></p><ul><li><strong>1-2 :</strong> Effleurage superficiel – poids de la main uniquement</li><li><strong>3-4 :</strong> Effleurage appuyé – ajout d'un léger poids du bras</li><li><strong>5-6 :</strong> Pétrissage doux – pression modérée avec les paumes</li><li><strong>7-8 :</strong> ❌ Trop profond pour le massage prénatal</li><li><strong>9-10 :</strong> ❌ Interdit – risque de lésion</li></ul><p><strong>En massage prénatal, on travaille entre 2 et 5 sur cette échelle.</strong></p><p><strong>Exercice pratique :</strong> Par binôme, s'exercer à appliquer les pressions 2, 3 et 5 sur l'avant-bras du partenaire. Le partenaire donne un retour sur la sensation ressentie.</p>` },
        { title: "Ergonomie avancée du praticien", content: `<p>Après l'introduction à la posture (Jour 1), nous approfondissons l'ergonomie pour prévenir les TMS (troubles musculo-squelettiques) :</p><p><strong>Utilisation du poids du corps :</strong></p><ul><li>La pression ne doit <strong>jamais</strong> venir de la force des bras ou des poignets</li><li>Transférer le poids du corps vers l'avant en fléchissant les genoux</li><li>Utiliser le mouvement de balancier avant/arrière pour moduler la pression</li><li>Les bras restent détendus, ce sont des « prolongements » du corps</li></ul><p><strong>Protection des pouces :</strong></p><ul><li>Ne jamais hyperétendre les pouces – toujours les utiliser en « bloc » avec la main</li><li>Alterner les techniques : paumes, pouces, avant-bras, coudes (pas de coude en prénatal)</li><li>Étirer régulièrement les pouces et les poignets entre les séances</li></ul><p><strong>Respiration du praticien :</strong></p><ul><li>Synchroniser sa respiration avec ses mouvements : inspirer en remontant, expirer en descendant</li><li>Ne jamais bloquer sa respiration (signe de tension excessive)</li><li>Respirer par le nez, calmement et régulièrement</li></ul><p><strong>Auto-étirements entre les séances :</strong></p><ol><li>Étirement des fléchisseurs du poignet (30 secondes par côté)</li><li>Rotation des épaules (10 cercles avant, 10 cercles arrière)</li><li>Étirement du psoas et des quadriceps</li><li>Flexion/extension de la colonne cervicale</li></ol>` },
        { title: "Massage du visage", content: `<p>Le massage du visage procure une détente profonde et rapide. Il est particulièrement apprécié en début ou fin de séance :</p><p><strong>Protocole en 8 étapes (10-15 minutes) :</strong></p><ol><li><strong>Pose des mains :</strong> Mains en coupelle sur le visage, immobiles, 10 secondes. Transfert de chaleur.</li><li><strong>Front :</strong> Lissage alterné du centre vers les tempes, avec les pouces. 6 passages. Soulage les céphalées de tension.</li><li><strong>Sourcils :</strong> Pincements légers le long de l'arcade sourcilière, de l'intérieur vers l'extérieur. 3 passages.</li><li><strong>Tempes :</strong> Pressions circulaires douces avec les index et majeurs. 8 cercles. Zone de grande détente.</li><li><strong>Pommettes :</strong> Effleurage du nez vers les oreilles, avec les pouces. 4 passages.</li><li><strong>Mâchoire :</strong> Pétrissage léger des masséters (muscles de la mâchoire). La femme enceinte serre souvent la mâchoire inconsciemment. 6 cercles.</li><li><strong>Menton :</strong> Pincements légers le long du menton, du centre vers les oreilles. 3 passages.</li><li><strong>Oreilles :</strong> Massage de l'ensemble du pavillon, du lobe vers le sommet. Tiraillement doux du lobe. Très relaxant.</li></ol><p><strong>Produit :</strong> Huile de jojoba ou crème hydratante neutre. Pas d'huile trop grasse sur le visage.</p>` },
        { title: "Massage des épaules et du cou", content: `<p>Les épaules et le cou sont les zones les plus tendues chez la femme enceinte en raison du poids des seins et de la posture compensatoire :</p><p><strong>Protocole épaules (position semi-assise ou latérale) :</strong></p><ol><li><strong>Effleurage d'ensemble :</strong> Mains à plat, du sommet des épaules vers la base du cou, puis retour par les bras. 5 passages pour réchauffer les tissus.</li><li><strong>Pétrissage des trapèzes :</strong> Saisir le trapèze entre le pouce et les doigts, presser doucement et relâcher. Attention au point Jianjing (VB21) – rester en-dessous, ne pas masser le sommet de l'épaule.</li><li><strong>Pressions glissées cervicales :</strong> Pouces de chaque côté de la colonne cervicale (jamais sur les vertèbres), glissement de la base du crâne vers les épaules. 4 passages.</li><li><strong>Points de tension :</strong> Pressions statiques de 5 secondes sur les points douloureux identifiés, relâchement progressif.</li><li><strong>Friction des sous-occipitaux :</strong> Bouts des doigts à la base du crâne, petits cercles. Zone idéale contre les céphalées.</li></ol><p><strong>⚠ Précautions :</strong></p><ul><li>Ne jamais tirer ou tourner brusquement la tête</li><li>Éviter le point Jianjing sur le sommet de l'épaule</li><li>Pression modérée uniquement – les ligaments cervicaux sont assouplis par la relaxine</li></ul>` },
        { title: "Fluidité et enchaînement des gestes", content: `<p>La fluidité des enchaînements distingue un massage professionnel d'un massage amateur :</p><p><strong>Principes d'enchaînement :</strong></p><ul><li><strong>Continuité du contact :</strong> Ne jamais rompre le contact avec la cliente. Quand une main se déplace, l'autre reste posée. Le retrait du contact doit être progressif.</li><li><strong>Transitions douces :</strong> Passer d'une zone à une autre par des effleurages de liaison (ex : du cou vers l'épaule, de l'épaule vers le bras).</li><li><strong>Rythme constant :</strong> Maintenir une cadence régulière – ni trop rapide (anxiogène) ni trop lente (endormissement non souhaité pendant les exercices pratiques).</li><li><strong>Respiration synchronisée :</strong> Ralentir le rythme du massage pendant l'expiration de la cliente pour amplifier la détente.</li></ul><p><strong>Exercice de fluidité (20 minutes en binôme) :</strong></p><ol><li>Réaliser un enchaînement complet : visage → cou → épaules sans jamais rompre le contact</li><li>Le « client » ferme les yeux et signale toute rupture de contact ou geste brusque</li><li>Le formateur observe et corrige les transitions</li></ol><p><strong>Critères d'évaluation :</strong> Continuité du toucher, régularité du rythme, qualité des transitions, posture du praticien, communication non-verbale.</p>` },
      ]
    },
    {
      title: "Jour 4 – Protocole complet partie 1 : haut du corps",
      description: "Maîtriser le massage des bras, des mains et du haut du corps. Techniques de drainage doux et relaxation.",
      sections: [
        { title: "Massage des bras : effleurage et drainage", content: `<p>Les bras de la femme enceinte peuvent présenter des œdèmes et une sensation de lourdeur, particulièrement au 3ème trimestre :</p><p><strong>Protocole bras (8-10 minutes par bras) :</strong></p><ol><li><strong>Effleurage global :</strong> Main à plat, du poignet vers l'épaule en un mouvement continu. Retour par la face externe. 5 passages.</li><li><strong>Pétrissage de l'avant-bras :</strong> Saisir les muscles de l'avant-bras entre les pouces et les doigts, pétrir doucement de manière alternée. 3 passages du poignet au coude.</li><li><strong>Drainage du bras :</strong> Mouvements de pompage légers, toujours du poignet vers l'épaule (sens du retour veineux). Pression légère et régulière.</li><li><strong>Friction du coude :</strong> Petits cercles avec les pouces autour de l'articulation du coude. Zone souvent oubliée mais très agréable.</li><li><strong>Pétrissage du biceps/triceps :</strong> Pétrissage doux des muscles du bras, de la même manière que pour l'avant-bras.</li><li><strong>Effleurage de clôture :</strong> Reprendre l'effleurage global, avec une pression décroissante. 3 passages.</li></ol><p><strong>Attention :</strong> Chez la femme enceinte, ne pas comprimer le creux du coude (zone vasculaire). Si un cathéter de perfusion est en place (hospitalisation), ne pas masser le bras concerné.</p>` },
        { title: "Massage des mains : réflexologie douce", content: `<p>Le massage des mains est une technique particulièrement relaxante qui peut être pratiquée dans toutes les positions :</p><p><strong>Protocole mains (5-8 minutes par main) :</strong></p><ol><li><strong>Prise de contact :</strong> Envelopper la main de la cliente entre les deux mains du praticien. Chaleur et présence pendant 10 secondes.</li><li><strong>Effleurage du dos de la main :</strong> Pouces en glissement du poignet vers les doigts, entre les métacarpiens. 4 passages.</li><li><strong>Massage de la paume :</strong> Pouces en mouvements circulaires sur l'ensemble de la paume. Insister sur le centre (point Laogong – détente profonde). 1 minute.</li><li><strong>Mobilisation des doigts :</strong> Chaque doigt est massé de la base à l'extrémité par un mouvement de rotation-traction douce. Finir par une légère traction axiale de chaque doigt.</li><li><strong>Mobilisation du poignet :</strong> Flexion/extension douce, rotations dans les deux sens. 5 rotations dans chaque direction.</li><li><strong>Étirement des espaces interdigitaux :</strong> Écarter doucement les doigts en tirant dans les espaces entre eux.</li></ol><p><strong>⚠ Point d'acupression à éviter :</strong> Le point Hegu (GI4) entre le pouce et l'index – ne pas appuyer dessus car il peut stimuler les contractions utérines.</p>` },
        { title: "Techniques de drainage doux du haut du corps", content: `<p>Le drainage lymphatique manuel (DLM) adapté au massage prénatal est une technique douce visant à réduire la rétention d'eau :</p><p><strong>Principes du drainage :</strong></p><ul><li>Pression <strong>très légère</strong> (poids d'une pièce de monnaie)</li><li>Mouvement toujours dirigé vers les ganglions lymphatiques les plus proches</li><li>Rythme lent et régulier (6-8 mouvements par minute)</li><li>Pas de lubrification (ou très peu) – le drainage se fait sur peau sèche ou avec un minimum d'huile</li></ul><p><strong>Protocole drainage haut du corps :</strong></p><ol><li><strong>Activation des ganglions cervicaux :</strong> Mouvements circulaires doux sous les oreilles et le long du cou. 5 cercles.</li><li><strong>Drainage du visage :</strong> Du centre du visage vers les oreilles, puis descente le long du cou vers les clavicules.</li><li><strong>Drainage des bras :</strong> Du bout des doigts vers les ganglions axillaires (aisselles). Mouvements de pompage légers.</li><li><strong>Activation des ganglions axillaires :</strong> Pressions circulaires très douces dans le creux axillaire.</li></ol><p><strong>Bénéfices spécifiques grossesse :</strong> Réduction des œdèmes des mains et du visage (syndrome du canal carpien fréquent au 3ème trimestre), amélioration du teint, diminution de la sensation de « gonflement ».</p>` },
        { title: "Techniques de relaxation intégrées", content: `<p>Entre les manœuvres de massage, des techniques de relaxation peuvent être intégrées pour approfondir la détente :</p><p><strong>Technique 1 : Le balancement</strong></p><ul><li>Saisir doucement le bras de la cliente et imprimer un léger mouvement de balancement, comme un berceau</li><li>La vibration se transmet au reste du corps</li><li>Durée : 30 secondes par membre</li></ul><p><strong>Technique 2 : La compression chaude</strong></p><ul><li>Poser les paumes chaudes sur une zone (épaules, nuque, sacrum)</li><li>Maintenir la position immobile pendant 15-20 secondes</li><li>La chaleur des mains pénètre les tissus et favorise le relâchement musculaire</li></ul><p><strong>Technique 3 : La visualisation guidée</strong></p><ul><li>Pendant le massage, guider la cliente avec la voix : « Imaginez que votre bébé flotte paisiblement dans son nid douillet… »</li><li>Ton de voix bas, lent, apaisant</li><li>Laisser des silences pour que la cliente crée ses propres images</li></ul><p><strong>Technique 4 : L'harmonisation sonore</strong></p><ul><li>Certains praticiens utilisent un bol tibétain ou un carillon pour marquer le début et la fin de la séance</li><li>Les vibrations sonores ajoutent une dimension sensorielle au massage</li><li>Vérifier que la cliente apprécie (certaines femmes enceintes sont hypersensibles aux sons)</li></ul>` },
        { title: "Mise en pratique : séquence complète haut du corps", content: `<p><strong>Exercice dirigé – Séquence de 25 minutes :</strong></p><p>Le formateur démontre puis chaque binôme pratique la séquence complète dans l'ordre suivant :</p><table border="1" cellpadding="8" style="width:100%;border-collapse:collapse"><tr style="background:#f0f0f0"><th>Étape</th><th>Zone</th><th>Durée</th><th>Techniques</th></tr><tr><td>1</td><td>Prise de contact</td><td>1 min</td><td>Mains posées sur les épaules, respiration synchronisée</td></tr><tr><td>2</td><td>Visage</td><td>5 min</td><td>Front, tempes, mâchoire, oreilles</td></tr><tr><td>3</td><td>Cou</td><td>3 min</td><td>Pressions glissées, friction sous-occipitale</td></tr><tr><td>4</td><td>Épaules</td><td>5 min</td><td>Pétrissage trapèzes, points de tension</td></tr><tr><td>5</td><td>Bras droit</td><td>4 min</td><td>Effleurage, pétrissage, drainage</td></tr><tr><td>6</td><td>Main droite</td><td>3 min</td><td>Paume, doigts, mobilisations</td></tr><tr><td>7</td><td>Bras gauche + main</td><td>7 min</td><td>Même séquence que bras droit</td></tr><tr><td>8</td><td>Clôture</td><td>2 min</td><td>Compression chaude épaules, retrait progressif</td></tr></table><p><strong>Critères d'évaluation :</strong> Fluidité, continuité du contact, qualité de la pression, respect du timing, confort de la « cliente », posture du praticien.</p>` },
      ]
    },
    {
      title: "Jour 5 – Protocole complet partie 2 : ventre, jambes et pieds",
      description: "Maîtriser le massage du ventre, de la poitrine, des jambes et des pieds avec les adaptations spécifiques à la grossesse.",
      sections: [
        { title: "Massage du ventre : techniques sécurisées", content: `<p>Le massage du ventre est un moment privilégié de connexion mère-bébé, mais il requiert une grande délicatesse :</p><p><strong>Conditions préalables :</strong></p><ul><li>Uniquement au 2ème trimestre (après accord de la cliente et avis médical favorable)</li><li>Au 3ème trimestre : effleurage très léger uniquement, ou massage suspendu</li><li>Toujours demander l'autorisation explicite de la cliente</li><li>Position semi-assise recommandée (ventre accessible sans compression)</li></ul><p><strong>Protocole ventre (5-8 minutes) :</strong></p><ol><li><strong>Prise de contact :</strong> Poser les deux mains à plat sur le ventre. Immobiles. Sentir les mouvements du bébé. Chaleur et présence. 20 secondes.</li><li><strong>Effleurage circulaire :</strong> Mouvement circulaire doux dans le sens des aiguilles d'une montre (sens du transit intestinal). Mains à plat, très léger. 8 cercles.</li><li><strong>Effleurage en spirale :</strong> Spirale partant du nombril vers la périphérie, de plus en plus large. Très doux.</li><li><strong>Application d'huile anti-vergetures :</strong> Utiliser de l'huile d'argan ou d'amande douce. Effleurage ascendant sur les côtés du ventre.</li><li><strong>Pause de connexion :</strong> Mains posées en coupelle sur le ventre. Inviter la maman à parler intérieurement à son bébé.</li></ol><p><strong>⚠ Règles absolues :</strong> Aucune pression – poids des mains uniquement. Aucun pétrissage. Aucune technique profonde. Si le bébé bouge beaucoup, c'est normal – signe qu'il réagit au toucher.</p>` },
        { title: "Massage de la poitrine et du thorax", content: `<p>La poitrine est une zone extrêmement sensible pendant la grossesse. Le massage du thorax peut soulager les tensions respiratoires :</p><p><strong>Précautions spécifiques :</strong></p><ul><li>Toujours demander le consentement explicite avant de toucher cette zone</li><li>Proposer à la cliente de garder son soutien-gorge si elle le souhaite</li><li>Ne jamais masser les mamelons (stimulation de l'ocytocine → contractions)</li><li>Utiliser des draps de couverture pour préserver la pudeur</li></ul><p><strong>Protocole thorax (5-7 minutes) :</strong></p><ol><li><strong>Effleurage intercostal :</strong> Pouces entre les côtes, du sternum vers les côtés. Mouvement d'ouverture thoracique. 4 passages.</li><li><strong>Étirement doux du grand pectoral :</strong> Mains sur les épaules, accompagner un mouvement d'ouverture vers l'arrière. Aide à la respiration.</li><li><strong>Massage du décolleté :</strong> Effleurage léger du creux de la gorge vers les épaules. Soulage la sensation d'oppression.</li><li><strong>Massage du sternum :</strong> Pressions glissées légères le long du sternum, de haut en bas. Point réflexe du thymus (immunité).</li></ol><p><strong>Bénéfices :</strong> Amélioration de la capacité respiratoire (réduite de 20% au 3ème trimestre), soulagement des tensions des muscles intercostaux, aide au drainage lymphatique mammaire.</p>` },
        { title: "Massage des jambes : drainage et soulagement", content: `<p>Les jambes sont la zone où les bénéfices du massage prénatal sont les plus spectaculaires :</p><p><strong>Problématiques fréquentes :</strong></p><ul><li>Œdèmes des chevilles et des pieds (80% des femmes enceintes au 3ème trimestre)</li><li>Sensation de jambes lourdes</li><li>Crampes nocturnes (mollets)</li><li>Varices et varicosités</li><li>Syndrome des jambes sans repos</li></ul><p><strong>Protocole jambes (10-15 minutes par jambe) :</strong></p><ol><li><strong>Effleurage ascendant global :</strong> Mains à plat, de la cheville vers la cuisse. Retour par l'extérieur de la jambe. 6 passages.</li><li><strong>Drainage des mollets :</strong> Mains en « V » autour du mollet, pompage ascendant doux. 4 passages.</li><li><strong>Pétrissage léger des mollets :</strong> Saisir le mollet entre les deux mains, pétrissage alternée doux. Attention aux crampes – si le muscle se contracte, stopper et étirer doucement.</li><li><strong>Drainage de la cuisse :</strong> Effleurage ascendant face externe et face interne (sans aller trop haut). 4 passages.</li><li><strong>Mobilisation de la rotule :</strong> Mouvements légers de la rotule dans toutes les directions. Soulage les douleurs ligamentaires.</li><li><strong>Effleurage de clôture :</strong> Reprendre l'effleurage global avec pression décroissante.</li></ol><p><strong>⚠ Zones à éviter :</strong> Creux poplité (arrière du genou), varices visibles, malléole interne (point Sanyinjiao).</p>` },
        { title: "Massage des pieds adapté à la grossesse", content: `<p>Le massage des pieds procure une sensation de bien-être immédiat et aide considérablement à réduire les œdèmes :</p><p><strong>Protocole pieds (8-10 minutes par pied) :</strong></p><ol><li><strong>Enveloppement thermique :</strong> Envelopper le pied entre les deux mains chaudes. Maintenir 15 secondes. Effet apaisant immédiat.</li><li><strong>Effleurage global :</strong> Du talon vers les orteils, puis dessus du pied du tibia vers les orteils. 4 passages.</li><li><strong>Massage de la voûte plantaire :</strong> Pouces en mouvements circulaires sur l'ensemble de la voûte. Pression modérée (cette zone est moins sensible). 1-2 minutes.</li><li><strong>Réflexologie douce – zone de détente :</strong> Pressions sur le centre de la voûte plantaire (plexus solaire). Point de relaxation profonde. 10 pressions de 3 secondes.</li><li><strong>Massage des orteils :</strong> Chaque orteil massé individuellement par rotation douce. Traction légère en fin de massage.</li><li><strong>Massage du dessus du pied :</strong> Pouces entre les métatarses, du pied vers les orteils. Aide à la circulation.</li><li><strong>Mobilisation de la cheville :</strong> Flexion/extension, rotation dans les deux sens. 5 rotations de chaque côté.</li><li><strong>Clôture :</strong> Enveloppement final du pied. Pression légère et décroissante.</li></ol><p><strong>⚠ Points d'acupression interdits :</strong></p><table border="1" cellpadding="8" style="width:100%;border-collapse:collapse"><tr style="background:#f0f0f0"><th>Point</th><th>Localisation exacte</th><th>Pourquoi l'éviter</th></tr><tr><td>Sanyinjiao (Rt6)</td><td>4 doigts au-dessus de la malléole interne</td><td>Stimule les contractions</td></tr><tr><td>Kunlun (V60)</td><td>Derrière la malléole externe</td><td>Favorise la dilatation du col</td></tr><tr><td>Taichong (F3)</td><td>Entre 1er et 2ème métatarse</td><td>Peut provoquer des saignements</td></tr></table>` },
        { title: "Adaptation selon le stade de grossesse", content: `<p>Le protocole de massage du bas du corps doit être adapté à chaque trimestre :</p><p><strong>2ème trimestre – Adaptation :</strong></p><ul><li>Pression modérée possible sur les mollets et cuisses</li><li>Massage du ventre avec effleurage léger autorisé</li><li>Durée de séance complète possible (60 minutes)</li><li>Position latérale ou semi-assise</li></ul><p><strong>3ème trimestre – Adaptation :</strong></p><ul><li>Réduire la pression à légère uniquement</li><li>Séance raccourcie (45 minutes maximum)</li><li>Focus principal sur le drainage et la relaxation</li><li>Changements de position fréquents (la cliente ne peut pas rester longtemps dans la même position)</li><li>Pause pipi possible en milieu de séance (pression utérine sur la vessie)</li></ul><p><strong>En cas de grossesse gémellaire :</strong></p><ul><li>Prudence maximale – séance de 30 minutes maximum</li><li>Uniquement des effleurages</li><li>Pas de massage du ventre</li><li>Certificat médical obligatoire</li></ul><p><strong>Exercice pratique :</strong> Simulation d'une séance complète du bas du corps (ventre → jambes → pieds) sur 30 minutes en binôme. Le formateur évalue la chronologie, les transitions et l'adaptation des techniques.</p>` },
      ]
    },
    {
      title: "Jour 6 – Protocole complet, relation client et évaluation",
      description: "Réaliser un massage complet autonome. Construire une relation client professionnelle. Évaluation pratique et théorique finale.",
      sections: [
        { title: "Massage du dos : protocole détaillé", content: `<p>Le massage du dos est le pilier de la séance de massage prénatal. Au jour 6, le protocole est approfondi :</p><p><strong>Installation :</strong> Cliente en décubitus latéral gauche, coussins bien positionnés. Le praticien se place derrière elle.</p><p><strong>Protocole dos complet (15-20 minutes) :</strong></p><ol><li><strong>Effleurage d'ouverture :</strong> Mains à plat, du sacrum vers les omoplates. Mouvement lent et enveloppant. 5 passages. Chaleur des mains sur les muscles paravertébraux.</li><li><strong>Pétrissage des paravertébraux :</strong> Pouces en mouvements circulaires de chaque côté de la colonne, du sacrum vers les cervicales. 3 passages aller-retour. Pression modérée.</li><li><strong>Pressions glissées profondes :</strong> Paumes dans les gouttières paravertébrales, de bas en haut. Pression soutenue mais confortable. 4 passages.</li><li><strong>Massage du sacrum :</strong> Mouvements circulaires avec la paume sur le sacrum. Zone de grande détente. 1 minute. Très apprécié pour soulager les douleurs pelviennes.</li><li><strong>Pétrissage des rhomboïdes :</strong> Entre les omoplates, pétrissage doux avec les pouces. Zone souvent très tendue.</li><li><strong>Points de trigger :</strong> Pressions statiques de 5-8 secondes sur les nœuds musculaires identifiés. Relâchement progressif.</li><li><strong>Effleurage de liaison :</strong> Transition du dos vers les hanches par des effleurages enveloppants.</li><li><strong>Massage des hanches/fessiers :</strong> Mouvements circulaires sur le grand fessier. Soulage les douleurs sciatiques fréquentes.</li><li><strong>Effleurage de clôture :</strong> Reprendre l'effleurage global avec pression décroissante. 3 passages.</li></ol>` },
        { title: "Massage de la tête et du cuir chevelu", content: `<p>Le massage crânien est un moment de grande détente qui clôture idéalement la séance :</p><p><strong>Protocole cuir chevelu (8-10 minutes) :</strong></p><ol><li><strong>Pose des mains :</strong> Mains en coupelle sur les tempes. Chaleur et immobilité. 10 secondes.</li><li><strong>Friction du cuir chevelu :</strong> Bouts des doigts écartés, mouvements circulaires sur l'ensemble du crâne, comme un shampooing. 2 minutes. Commence par les tempes, remonte vers le sommet, descend vers la nuque.</li><li><strong>Pression du sommet du crâne :</strong> Pression statique douce avec la paume sur le vertex (sommet du crâne). Point de grande relaxation. 10 secondes.</li><li><strong>Traction douce des cheveux :</strong> Saisir de petites mèches à la base et tirer doucement pendant 3 secondes. Très relaxant et stimule la circulation du cuir chevelu.</li><li><strong>Massage de la base du crâne :</strong> Pouces sur les muscles sous-occipitaux, petits cercles appuyés. Point d'élection contre les céphalées. 1 minute.</li><li><strong>Effleurage final :</strong> Lissage lent de la racine des cheveux vers les pointes. 5 passages. Signal de clôture.</li></ol><p><strong>Bénéfices :</strong> Réduction des céphalées de tension (très fréquentes pendant la grossesse), stimulation du système parasympathique, amélioration du sommeil, sensation de légèreté mentale.</p><p><strong>Produit :</strong> Pas d'huile sur le cuir chevelu (sauf demande de la cliente). Mains sèches pour une meilleure friction.</p>` },
        { title: "Construction d'une séance complète", content: `<p>L'objectif final est de savoir structurer et réaliser une séance complète de massage prénatal de 60 minutes :</p><table border="1" cellpadding="8" style="width:100%;border-collapse:collapse"><tr style="background:#f0f0f0"><th>Phase</th><th>Durée</th><th>Contenu détaillé</th></tr><tr><td><strong>1. Accueil & Anamnèse</strong></td><td>5 min</td><td>Accueil chaleureux, vérification des contre-indications, état du jour (douleurs, humeur, sommeil), attentes spécifiques</td></tr><tr><td><strong>2. Installation</strong></td><td>3 min</td><td>Position latérale gauche, placement des coussins, vérification du confort, réglage lumière/musique</td></tr><tr><td><strong>3. Recentrage & Respiration</strong></td><td>5 min</td><td>Respiration guidée, balayage corporel, connexion mère-bébé</td></tr><tr><td><strong>4. Massage du dos</strong></td><td>15 min</td><td>Effleurage, pétrissage, pressions glissées, sacrum, hanches</td></tr><tr><td><strong>5. Massage des jambes</strong></td><td>10 min</td><td>Drainage ascendant, pétrissage mollets, mobilisations</td></tr><tr><td><strong>6. Massage des pieds</strong></td><td>8 min</td><td>Voûte plantaire, orteils, mobilisation chevilles</td></tr><tr><td><strong>7. Changement de côté</strong></td><td>2 min</td><td>Réinstallation latérale droite pour les zones non massées</td></tr><tr><td><strong>8. Massage des bras & mains</strong></td><td>5 min</td><td>Drainage, pétrissage, réflexologie main</td></tr><tr><td><strong>9. Massage crâne & visage</strong></td><td>5 min</td><td>Cuir chevelu, visage, oreilles</td></tr><tr><td><strong>10. Retour au calme</strong></td><td>2 min</td><td>Compression chaude, respiration finale, retrait progressif du contact</td></tr></table>` },
        { title: "Relation client et prise de contact", content: `<p>La dimension relationnelle est aussi importante que la technique dans le massage prénatal :</p><p><strong>Avant la première séance :</strong></p><ul><li>Entretien téléphonique : présentation, questionnaire de santé préliminaire</li><li>Envoi des documents : programme, tarifs, conditions générales, questionnaire médical</li><li>Confirmation de rendez-vous par SMS 24h avant</li></ul><p><strong>Accueil en cabinet :</strong></p><ul><li>Espace d'attente confortable et chaleureux</li><li>Proposer une boisson chaude (tisane de fruits – pas de thé/café)</li><li>Présentation personnelle et de l'espace de travail</li><li>Écoute active : laisser la cliente exprimer ses attentes et ses inquiétudes</li></ul><p><strong>Communication pendant la séance :</strong></p><ul><li>Annoncer chaque zone avant de la toucher : « Je vais maintenant travailler sur votre dos… »</li><li>Demander régulièrement si la pression convient</li><li>Respecter les silences – ne pas forcer la conversation</li><li>Observer les réactions non-verbales (tension musculaire = inconfort)</li></ul><p><strong>Après la séance :</strong></p><ul><li>Laisser la cliente se relever à son rythme (risque d'hypotension orthostatique)</li><li>Proposer un verre d'eau</li><li>Donner les conseils post-séance (hydratation, repos, étirements)</li><li>Proposer le prochain rendez-vous</li></ul>` },
        { title: "Mise en place d'un protocole professionnel", content: `<p>Pour exercer de manière professionnelle, le praticien doit structurer son activité :</p><p><strong>Documents obligatoires :</strong></p><ul><li><strong>Fiche d'anamnèse :</strong> Données personnelles, antécédents médicaux, stade de grossesse, contre-indications</li><li><strong>Consentement éclairé :</strong> Document signé par la cliente reconnaissant avoir été informée des risques et limites du massage</li><li><strong>Fiche de suivi :</strong> Résumé de chaque séance (zones travaillées, réactions, observations)</li><li><strong>Factures et reçus :</strong> Conformes aux obligations fiscales</li></ul><p><strong>Tarification :</strong></p><table border="1" cellpadding="8" style="width:100%;border-collapse:collapse"><tr style="background:#f0f0f0"><th>Prestation</th><th>Durée</th><th>Tarif indicatif</th></tr><tr><td>Séance découverte</td><td>30 min</td><td>35-50€</td></tr><tr><td>Séance standard</td><td>60 min</td><td>60-90€</td></tr><tr><td>Séance premium (+ visage + crâne)</td><td>90 min</td><td>90-120€</td></tr><tr><td>Forfait 5 séances</td><td>5 × 60 min</td><td>270-400€</td></tr></table><p><strong>Assurance professionnelle :</strong> Obligatoire – Responsabilité Civile Professionnelle (RCP) couvrant les soins corporels de bien-être. Coût annuel : 150-300€.</p>` },
        { title: "Évaluation pratique et théorique", content: `<p>L'évaluation de fin de formation se compose de trois parties :</p><p><strong>Partie 1 : Évaluation théorique (30 minutes)</strong></p><ul><li>QCM de 20 questions couvrant : anatomie, contre-indications, produits, points d'acupression, cadre légal</li><li>Note minimale requise : 14/20</li></ul><p><strong>Partie 2 : Évaluation pratique (60 minutes)</strong></p><ul><li>Réalisation d'un massage prénatal complet sur un « client-test »</li><li>Chronomètre : respect du timing de la séance (55-65 minutes)</li></ul><p><strong>Grille d'évaluation pratique :</strong></p><table border="1" cellpadding="8" style="width:100%;border-collapse:collapse"><tr style="background:#f0f0f0"><th>Critère</th><th>Points</th></tr><tr><td>Installation et positionnement de la cliente</td><td>/10</td></tr><tr><td>Qualité de l'accueil et de l'anamnèse</td><td>/10</td></tr><tr><td>Maîtrise des techniques de base</td><td>/20</td></tr><tr><td>Respect des contre-indications et points à éviter</td><td>/20</td></tr><tr><td>Fluidité et enchaînement des gestes</td><td>/15</td></tr><tr><td>Communication et écoute de la cliente</td><td>/10</td></tr><tr><td>Posture et ergonomie du praticien</td><td>/10</td></tr><tr><td>Gestion du temps</td><td>/5</td></tr><tr><td><strong>Total</strong></td><td><strong>/100</strong></td></tr></table><p><strong>Partie 3 : Grille d'acquisition des compétences</strong></p><ul><li>Auto-évaluation + évaluation par le formateur</li><li>Identification des axes de progression post-formation</li></ul><p><strong>Attestation :</strong> Délivrée si score théorique ≥ 14/20 ET score pratique ≥ 70/100.</p>` },
        { title: "Ressources complémentaires et plan d'action post-formation", content: `<p><strong>Bibliographie recommandée :</strong></p><ul><li><em>Le massage prénatal</em> – Suzanne Yates (Éditions Le Souffle d'Or)</li><li><em>Massage for Common Ailments in Pregnancy</em> – Dr. Moira Dune</li><li><em>Anatomie pour le mouvement</em> – Blandine Calais-Germain</li><li><em>Accompagner la naissance</em> – Michel Odent</li></ul><p><strong>Sites web et organisations :</strong></p><ul><li>Fédération Française du Massage Bien-Être (FFMBE) : <a href="https://www.ffmbe.fr">www.ffmbe.fr</a></li><li>Chambre Nationale des Praticiens en Massage Bien-Être</li><li>Institut Français de Massage : formation continue et spécialisations</li></ul><p><strong>Plan d'action post-formation :</strong></p><ol><li><strong>Semaines 1-2 :</strong> Pratiquer sur des proches (au moins 5 séances gratuites pour acquérir de l'assurance)</li><li><strong>Semaines 3-4 :</strong> Finaliser les documents professionnels (anamnèse, consentement, tarifs)</li><li><strong>Mois 2 :</strong> Souscrire l'assurance RCP, déclarer l'activité</li><li><strong>Mois 3 :</strong> Lancer l'activité – premiers clients payants, créer une page professionnelle</li><li><strong>Mois 6 :</strong> Bilan de compétences, identifier les besoins en formation continue</li></ol><p><strong>Formations complémentaires suggérées :</strong> Massage postnatal, réflexologie plantaire, aromathérapie grossesse (avec un aromathérapeute certifié), sophrologie prénatale.</p>` },
      ]
    },
  ];
}
